#!/usr/bin/env python3
"""Form demo: parses the HTML form and counts its fields."""
from html.parser import HTMLParser
HTML = '<form action="#" method="post">\n<h2>Signature Maker Mark Registration</h2>\n<label>Creator name<br><input type="text" name="creator" required></label><br><br>\n<label>Mark description<br><textarea name="mark_desc" rows="4" cols="40" required></textarea></label><br><br>\n<label>First use date<br><input type="date" name="first_use" required></label><br><br>\n<label>Stamp code<br><input type="text" name="stamp" required></label><br><br>\n<button type="submit">Submit</button>\n</form>'
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.inputs=[]; self.in_form=False
    def handle_starttag(self,t,a):
        if t=='form': self.in_form=True
        if t in ('input','textarea','select') and self.in_form:
            self.inputs.append(t)
    def handle_endtag(self,t):
        if t=='form': self.in_form=False
p=P(); p.feed(HTML)
assert p.inputs, 'form must contain fields'
print('OK: form has %d fillable fields (%s)' % (len(p.inputs), ', '.join(sorted(set(p.inputs)))))
if __name__=='__main__':
    pass

